<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
    <title>Yoru Shield VPN</title>
    <!-- Firebase só sob demanda (chat/cloud) — não bloqueia abertura da UI -->
    <script>
      window.__loadFirebase = function(cb) {
        if (window.firebase) { if (cb) cb(); return; }
        if (window.__fbLoading) { window.__fbLoading.push(cb); return; }
        window.__fbLoading = cb ? [cb] : [];
        var a = document.createElement('script');
        a.src = 'https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js';
        a.onload = function() {
          var b = document.createElement('script');
          b.src = 'https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore-compat.js';
          b.onload = function() {
            var q = window.__fbLoading || []; window.__fbLoading = null;
            q.forEach(function(fn){ try{ fn&&fn(); }catch(e){} });
          };
          document.head.appendChild(b);
        };
        document.head.appendChild(a);
      };
    </script>
    <style>
        /* Fontes do sistema = zero download + paint mais barato no WebView */
        :root {
            --bg-main: #0a0e17;
            --bg-card: #131824;
            --bg-card-solid: #131824;
            --border: rgba(255, 255, 255, 0.08);
            --text-main: #f8fafc;
            --text-muted: #94a3b8;
            --accent-indigo: #6366f1;
            --accent-cyan: #06b6d4;
            --accent-a: #6366f1;
            --accent-b: #06b6d4;
            --success: #10b981;
            --warning: #f59e0b;
            --danger: #ef4444;
            --nav-h: 75px;
            --glass-blur: none; /* padrão LEVE: blur mata GPU no Android */
            --orb-glow: transparent;
            --bg-glow1: transparent;
            --bg-glow2: transparent;
            --safe-top: env(safe-area-inset-top, 0px);
            --card-shadow: none;
        }

        [data-theme="light"] {
            --bg-main: #f0f4ff;
            --bg-card: rgba(255,255,255,0.75);
            --bg-card-solid: #ffffff;
            --border: rgba(0,0,0,0.08);
            --text-main: #0f172a;
            --text-muted: #64748b;
            --accent-indigo: #4f46e5;
            --accent-cyan: #0891b2;
            --accent-a: #4f46e5;
            --accent-b: #0891b2;
            --orb-glow: rgba(79,70,229,0.2);
            --bg-glow1: rgba(99,102,241,0.1);
            --bg-glow2: rgba(6,182,212,0.1);
        }
        [data-theme="light"] .bottom-nav { background: rgba(255,255,255,0.85); }

        /* ═══ MODO LEVE (padrão) vs BELO ═══ */
        html[data-beauty="on"] {
            --bg-card: rgba(20, 25, 38, 0.55);
            --glass-blur: blur(10px);
            --orb-glow: rgba(99,102,241,0.25);
            --bg-glow1: rgba(99, 102, 241, 0.08);
            --bg-glow2: rgba(6, 182, 212, 0.08);
            --card-shadow: 0 8px 24px rgba(0,0,0,0.25);
        }
        html[data-beauty="on"] .yoru-card {
            background: var(--bg-card);
            backdrop-filter: var(--glass-blur);
            -webkit-backdrop-filter: var(--glass-blur);
        }
        html[data-beauty="on"] .bottom-nav {
            background: rgba(15,20,30,0.85);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
        }
        /* Páginas ocultas: não pintam / não compõem */
        .page { content-visibility: auto; contain: layout style paint; }
        .page:not(.active) { display: none !important; content-visibility: hidden; }
        /* Efeitos decorativos desligados no modo leve */
        html:not([data-beauty="on"]) .floating-bubble,
        html:not([data-beauty="on"]) .fx-star,
        html:not([data-beauty="on"]) .celestial-body,
        html:not([data-beauty="on"]) .wallpaper-overlay {
            display: none !important;
            animation: none !important;
        }
        html:not([data-beauty="on"]) .bg-orb,
        html:not([data-beauty="on"]) .glow-orb {
            display: none !important;
        }
        /* Transições mais curtas em tudo no modo leve */
        html:not([data-beauty="on"]) * {
            scroll-behavior: auto !important;
        }
        html:not([data-beauty="on"]) .yoru-card:active {
            transform: none;
        }
        /* blocked overlay sem blur */
        .blocked-overlay {
            backdrop-filter: none !important;
            -webkit-backdrop-filter: none !important;
            background: rgba(10,14,23,0.72) !important;
        }
        html[data-beauty="on"] .blocked-overlay {
            backdrop-filter: blur(3px);
            -webkit-backdrop-filter: blur(3px);
        }

        [data-theme="light"] .nav-btn { color: #94a3b8; }
        [data-theme="light"] .nav-btn.active { color: var(--accent-indigo); background: rgba(79,70,229,0.07); }
        [data-theme="light"] .modal-box { background: #f8faff; }
        [data-theme="light"] .input-field input { color: #0f172a; }
        [data-theme="light"]
        [data-theme="light"] .toast { background: rgba(255,255,255,0.97); color: #0f172a; }
        [data-theme="light"] .wallpaper-overlay { opacity: 0.15; }

        [data-theme="red"] { --bg-main:#100808;--bg-card:rgba(40,12,12,0.65);--bg-card-solid:#1a0909;--border:rgba(255,80,80,0.12);--text-main:#fff5f5;--text-muted:#f87171;--accent-indigo:#ef4444;--accent-cyan:#fb923c;--accent-a:#ef4444;--accent-b:#fb923c;--orb-glow:rgba(239,68,68,0.3);--bg-glow1:rgba(239,68,68,0.1);--bg-glow2:rgba(251,146,60,0.08); }
        [data-theme="blue"] { --bg-main:#050d1a;--bg-card:rgba(8,20,50,0.65);--bg-card-solid:#08132e;--border:rgba(59,130,246,0.15);--text-main:#eff6ff;--text-muted:#93c5fd;--accent-indigo:#3b82f6;--accent-cyan:#22d3ee;--accent-a:#3b82f6;--accent-b:#22d3ee;--orb-glow:rgba(59,130,246,0.3);--bg-glow1:rgba(59,130,246,0.1);--bg-glow2:rgba(34,211,238,0.08); }
        [data-theme="gold"] { --bg-main:#0d0a00;--bg-card:rgba(35,28,0,0.65);--bg-card-solid:#1a1500;--border:rgba(234,179,8,0.15);--text-main:#fefce8;--text-muted:#fde047;--accent-indigo:#eab308;--accent-cyan:#f97316;--accent-a:#eab308;--accent-b:#f97316;--orb-glow:rgba(234,179,8,0.3);--bg-glow1:rgba(234,179,8,0.1);--bg-glow2:rgba(249,115,22,0.08); }
        [data-theme="neon"] { --bg-main:#020d06;--bg-card:rgba(4,28,12,0.65);--bg-card-solid:#041a0a;--border:rgba(16,185,129,0.15);--text-main:#f0fdf4;--text-muted:#6ee7b7;--accent-indigo:#10b981;--accent-cyan:#34d399;--accent-a:#10b981;--accent-b:#34d399;--orb-glow:rgba(16,185,129,0.3);--bg-glow1:rgba(16,185,129,0.1);--bg-glow2:rgba(52,211,153,0.08); }
        [data-theme="rose"] { --bg-main:#0f0510;--bg-card:rgba(35,8,38,0.65);--bg-card-solid:#1a0520;--border:rgba(244,114,182,0.15);--text-main:#fdf4ff;--text-muted:#f0abfc;--accent-indigo:#ec4899;--accent-cyan:#a855f7;--accent-a:#ec4899;--accent-b:#a855f7;--orb-glow:rgba(236,72,153,0.3);--bg-glow1:rgba(236,72,153,0.1);--bg-glow2:rgba(168,85,247,0.08); }
        [data-theme="pulse"] {
            --bg-main:#07050f;--bg-card:rgba(20,12,40,0.65);--bg-card-solid:#10082a;--border:rgba(139,92,246,0.15);--text-main:#f5f3ff;--text-muted:#c4b5fd;--accent-indigo:#8b5cf6;--accent-cyan:#06b6d4;--accent-a:#8b5cf6;--accent-b:#06b6d4;--orb-glow:rgba(139,92,246,0.35);--bg-glow1:rgba(139,92,246,0.12);--bg-glow2:rgba(6,182,212,0.08);
        }
        [data-theme="pulse"] .app-logo { background: linear-gradient(135deg, #8b5cf6, #ec4899, #06b6d4); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-size: 200%; animation: gradShift 3s ease infinite; }
        [data-theme="pulse"] .app-logo-icon { background: linear-gradient(135deg, #8b5cf6, #ec4899); animation: gradShift 3s ease infinite; }
        @keyframes gradShift { 0%,100%{background-position:0% 50%} 50%{background-position:100% 50%} }
        [data-theme="pulse"] .bottom-nav { border-color: rgba(139,92,246,0.2); box-shadow: 0 10px 40px rgba(139,92,246,0.2); }
        [data-theme="pulse"] .nav-btn.active svg { animation: colorCycle 4s linear infinite; }
        @keyframes colorCycle { 0%{color:#8b5cf6} 33%{color:#ec4899} 66%{color:#06b6d4} 100%{color:#8b5cf6} }

        [data-layout="compact"] .yoru-card { padding: 10px; border-radius: 14px; }
        [data-layout="compact"] .status-title { font-size: 20px; }
        [data-layout="compact"] .bottom-nav { height: 64px; border-radius: 18px; }
        [data-layout="extreme-glass"] .yoru-card { backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px); background: rgba(20, 25, 38, 0.3); border: 1px solid rgba(255,255,255,0.15); }
        [data-layout="extreme-glass"] .bottom-nav { background: rgba(15,20,30,0.6); backdrop-filter: blur(24px); }
        [data-layout="neumorphic"] .yoru-card { background: #e0e5ec; border: none; box-shadow: 8px 8px 16px rgba(163, 177, 198, 0.6), -8px -8px 16px rgba(255, 255, 255, 0.8); border-radius: 24px; }
        [data-layout="neumorphic"] .bottom-nav { background: #e0e5ec; box-shadow: 8px 8px 16px rgba(163, 177, 198, 0.6), -8px -8px 16px rgba(255, 255, 255, 0.8); border: none; }
        [data-layout="neumorphic"] .app-shell { background: #e0e5ec; }
        [data-layout="neumorphic"] .toast { background: #e0e5ec; color: #1e293b; }
        [data-layout="neumorphic"] .modal-box { background: #e0e5ec; }
        [data-layout="minimal"] .yoru-card { border-radius: 8px; backdrop-filter: none; -webkit-backdrop-filter: none; }
        [data-layout="minimal"] .bottom-nav { border-radius: 8px; backdrop-filter: none; background: rgba(15,20,30,0.95); }
        [data-layout="futuristic"] .yoru-card { border-radius: 4px; border-width: 1.5px; border-style: solid; border-color: rgba(6, 182, 212, 0.4); box-shadow: 0 0 10px rgba(0,229,255,0.2); }
        [data-layout="futuristic"] .bottom-nav { border-radius: 4px; border: 1.5px solid rgba(6, 182, 212, 0.4); box-shadow: 0 0 15px rgba(0,229,255,0.3); background: rgba(0,20,30,0.8); }
        [data-layout="futuristic"] .app-logo { font-family: 'Courier New', monospace; }

        * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin: 0; padding: 0; }

        /* Bloqueia seleção/cópia por long-press em toda a UI (WebView Android) */
        html, body, .app-shell, .page, .yoru-card, .server-card, .sc-title, .sc-sub, .sc-label,
        .stat-card, .stat-value, .stat-label, .nav-btn, .ui-chip, .sc-badge,
        .hero-area, .status-label, .status-sub, .btn-connect-main, .header-bar {
            -webkit-user-select: none !important;
            user-select: none !important;
            -webkit-touch-callout: none !important; /* sem menu Copiar/Colar no iOS/WebView */
            -webkit-user-drag: none;
        }

        /* Inputs e áreas de texto: pode selecionar/colar normalmente */
        input, textarea, [contenteditable="true"], .allow-select {
            -webkit-user-select: text !important;
            user-select: text !important;
            -webkit-touch-callout: default !important;
        }

        html, body { min-height: 100%; background: var(--bg-main); overflow-x: hidden; }

        body {
            font-family: 'Outfit', system-ui, sans-serif;
            color: var(--text-main);
            transition: background-color 0.4s ease, color 0.4s ease;
            background-image:
                radial-gradient(circle at 15% 50%, var(--bg-glow1), transparent 25%),
                radial-gradient(circle at 85% 30%, var(--bg-glow2), transparent 25%);
        }

        button { cursor: pointer; touch-action: manipulation; user-select: none; border: none; background: none; font-family: inherit; }

        .wallpaper-overlay {
            position: fixed; inset: 0; z-index: -2; pointer-events: none;
            background-image: none; /* só no modo belo */
            background-size: cover; background-position: center; background-repeat: no-repeat;
            opacity: 0.06; mix-blend-mode: screen; transition: opacity 0.4s;
        }

        .celestial-body {
            position: fixed; top: calc(25px + var(--safe-top)); right: 25px; font-size: 48px; z-index: 1; pointer-events: none;
            animation: floatCelestial 6s ease-in-out infinite alternate; transition: opacity 0.4s, filter 0.4s;
        }
        .celestial-sun { opacity: 0.35; filter: drop-shadow(0 0 12px rgba(255,200,0,0.25)); }
        [data-theme="light"] .celestial-sun { opacity: 1; filter: drop-shadow(0 0 24px rgba(255,200,0,0.9)); }
        .celestial-moon { filter: drop-shadow(0 0 18px rgba(255,255,255,0.6)); }
        @keyframes floatCelestial { 0%{transform:translateY(0px) rotate(-5deg)} 100%{transform:translateY(15px) rotate(5deg)} }

        .fx-star {
            position: fixed; background-color: #fff; border-radius: 50%; pointer-events: none; z-index: 0;
            opacity: 0; animation: twinkleStar linear infinite;
        }
        [data-theme="light"] .fx-star { background-color: #0f172a; }
        @keyframes twinkleStar { 0%{opacity:0;transform:scale(0.5)} 50%{opacity:0.6;transform:scale(1)} 100%{opacity:0;transform:scale(0.5)} }

        .floating-bubble {
            position: fixed; border-radius: 50%; pointer-events: none; z-index: 0;
            background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.15), rgba(99,102,241,0.1));
            animation: floatBubble ease-in-out infinite;
        }
        @keyframes floatBubble {
            0%{transform:translateY(0px) translateX(0px) scale(1)}
            25%{transform:translateY(-30px) translateX(15px) scale(1.1)}
            50%{transform:translateY(-15px) translateX(-10px) scale(0.95)}
            75%{transform:translateY(-40px) translateX(-20px) scale(1.05)}
            100%{transform:translateY(0px) translateX(0px) scale(1)}
        }

        .app-shell {
            width: min(100%, 480px); margin: 0 auto;
            min-height: 100vh; display: flex; flex-direction: column;
            padding-bottom: calc(var(--nav-h) + env(safe-area-inset-bottom) + 20px);
            padding-top: var(--safe-top);
            transition: margin-left 0.4s cubic-bezier(0.4,0,0.2,1), filter 0.3s; position: relative; z-index: 2;
        }

        .app-header { display: flex; justify-content: space-between; align-items: center; padding: 14px 16px; gap: 10px; }
        .app-logo {
            display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1;
        }
        .logo-text-wrap { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
        .logo-name {
            font-size: 17px; font-weight: 900; letter-spacing: -0.3px;
            background: linear-gradient(135deg, #fff, #c4b5fd);
            -webkit-background-clip: text; -webkit-text-fill-color: transparent;
            white-space: nowrap; line-height: 1.15;
        }
        .logo-ip {
            font-size: 11px; font-weight: 700; color: var(--accent-b);
            font-variant-numeric: tabular-nums;
            letter-spacing: 0.2px;
            white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
            max-width: 180px; line-height: 1.2;
        }
        .logo-meta {
            font-size: 10px; font-weight: 600; color: var(--text-muted);
            display: flex; align-items: center; gap: 4px; white-space: nowrap;
            overflow: hidden; text-overflow: ellipsis; line-height: 1.2;
        }
        .meta-sep { opacity: 0.4; }
        .app-logo-icon {
            width: 40px; height: 40px; border-radius: 12px;
            background: linear-gradient(135deg, var(--accent-a), var(--accent-b));
            display: grid; place-items: center; color: #fff; font-size: 14px;
            box-shadow: 0 4px 16px var(--orb-glow);
            -webkit-text-fill-color: #fff;
            overflow: hidden; padding: 0; flex-shrink: 0;
        }
        .app-logo-icon img {
            width: 100%; height: 100%; object-fit: cover; border-radius: 12px;
            display: block;
        }
        .header-right { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
        .app-version, .premium-badge {
            font-size: 10px; font-weight: 700; color: var(--text-muted);
            background: rgba(255,255,255,0.05); padding: 5px 10px; border-radius: 20px;
            border: 1px solid var(--border);
            display: flex; align-items: center; gap: 4px;
        }
        .premium-badge {
            background: linear-gradient(135deg, rgba(139,92,246,0.25), rgba(168,85,247,0.2));
            border-color: rgba(168,85,247,0.35);
            color: #c4b5fd;
        }

        .page { display: none; flex-direction: column; flex: 1; padding: 0 20px; animation: fadeIn 0.3s ease; }
        .page.active { display: flex; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

        .page-title-box { margin-bottom: 20px; }
        .page-title { font-size: 28px; font-weight: 800; color: var(--text-main); }
        .page-subtitle { font-size: 14px; color: var(--text-muted); font-weight: 400; margin-top: 4px; }

        .hero-area {
            display: flex; flex-direction: column; align-items: center;
            margin-top: 8px; margin-bottom: 20px; position: relative;
        }

        .status-row {
            display: flex; align-items: center; justify-content: center; gap: 10px;
            margin-bottom: 6px;
        }
        .status-dot {
            width: 10px; height: 10px; border-radius: 50%;
            background: var(--danger);
            box-shadow: 0 0 10px var(--danger);
            flex-shrink: 0;
            transition: background 0.3s, box-shadow 0.3s;
        }
        body.st-conectado .status-dot { background: var(--success); box-shadow: 0 0 12px var(--success); }
        body.st-conectando .status-dot { background: var(--warning); box-shadow: 0 0 12px var(--warning); animation: pulseDot 1s ease infinite; }
        body.st-erro .status-dot { background: var(--danger); box-shadow: 0 0 12px var(--danger); }
        @keyframes pulseDot { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.5;transform:scale(0.85)} }

        .status-title {
            font-size: 13px; font-weight: 800; text-align: center;
            color: var(--danger); transition: color 0.3s;
            letter-spacing: 1.5px; text-transform: uppercase;
        }
        body.st-conectado .status-title { color: var(--success); }
        body.st-conectando .status-title { color: var(--warning); }
        body.st-erro .status-title { color: var(--danger); }
        .status-sub {
            font-size: 13px; color: var(--text-muted); text-align: center;
            font-weight: 500; max-width: 85%; margin-bottom: 18px;
            letter-spacing: 0.3px;
        }

        /* ═══ BOTÃO DE ENERGIA CIRCULAR (estilo print) ═══ */
        .power-ring-wrap {
            position: relative;
            width: 180px; height: 180px;
            display: grid; place-items: center;
            margin: 4px 0 12px;
        }
        .power-ring {
            position: absolute; inset: 0; border-radius: 50%;
            border: 2px solid rgba(139,92,246,0.15);
            pointer-events: none;
        }
        .power-ring:nth-child(1) { inset: -8px; border-color: rgba(139,92,246,0.08); }
        .power-ring:nth-child(2) { inset: 8px; border-color: rgba(139,92,246,0.2); }
        .power-ring:nth-child(3) {
            inset: 20px;
            border: 1.5px solid rgba(168,85,247,0.35);
            box-shadow: 0 0 30px rgba(139,92,246,0.15), inset 0 0 20px rgba(139,92,246,0.05);
        }
        body.st-conectado .power-ring:nth-child(3) {
            border-color: rgba(16,185,129,0.45);
            box-shadow: 0 0 30px rgba(16,185,129,0.2), inset 0 0 20px rgba(16,185,129,0.08);
        }
        body.st-conectando .power-ring:nth-child(3) {
            border-color: rgba(245,158,11,0.45);
            box-shadow: 0 0 30px rgba(245,158,11,0.2);
            animation: ringSpin 2s linear infinite;
        }
        @keyframes ringSpin { to { transform: rotate(360deg); } }

        .btn-connect-main {
            width: 110px; height: 110px; border-radius: 50%;
            background: linear-gradient(145deg, #8b5cf6, #6d28d9 50%, #4c1d95);
            color: #fff; font-size: 0;
            cursor: pointer; transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
            box-shadow:
                0 0 0 6px rgba(139,92,246,0.15),
                0 0 40px rgba(139,92,246,0.45),
                0 12px 32px rgba(0,0,0,0.4),
                inset 0 2px 8px rgba(255,255,255,0.2);
            position: relative; overflow: hidden; z-index: 5;
            display: grid; place-items: center; flex: none; padding: 0;
            border: none;
        }
        .btn-connect-main::after {
            content: ''; position: absolute; inset: 0; border-radius: 50%;
            background: radial-gradient(circle at 35% 30%, rgba(255,255,255,0.25), transparent 55%);
            pointer-events: none;
        }
        .btn-connect-main:active { transform: scale(0.92); }
        .btn-connect-main:active::before {
            content: ''; position: absolute; inset: -20px; border-radius: 50%;
            background: radial-gradient(circle, rgba(255,255,255,0.3) 0%, transparent 60%);
            animation: ripple 0.6s ease-out;
        }
        @keyframes ripple { 0%{transform:scale(0);opacity:1} 100%{transform:scale(1);opacity:0} }

        .btn-connect-main svg {
            width: 42px; height: 42px;
            stroke-width: 2.2;
            filter: drop-shadow(0 2px 4px rgba(0,0,0,0.3));
            position: relative; z-index: 1;
        }
        #btn-connect-text { display: none; }

        body.st-conectado .btn-connect-main {
            background: linear-gradient(145deg, #34d399, #10b981 50%, #059669);
            box-shadow:
                0 0 0 6px rgba(16,185,129,0.2),
                0 0 40px rgba(16,185,129,0.5),
                0 12px 32px rgba(0,0,0,0.4),
