var _credsSaveTimer = null;

/**
 * Salva credenciais manuais no Android.
 * - NUNCA salva vazio (apagava USER/PASS do Config e quebrava Free)
 * - NUNCA sobrescreve quando login já vem do Config (embutido)
 * - immediate=true: grava AGORA (obrigatório antes de connect)
 */
function autoSaveCredentials(immediate) {
  // Login automático do Config: não mexe nas prefs de auth
  if (_hasEmbeddedCreds) return;

  var u  = (($('ci-user') || {}).value || '').trim();
  var p  = (($('ci-pass') || {}).value || '').trim();
  var v2 = (($('ci-xray') || {}).value || '').trim();

  // Não apagar credenciais já salvas com campos vazios
  if (!u && !p && !v2) return;

  function doSave() {
    try {
      if (window.Android && typeof window.Android.saveCredentials === 'function') {
        window.Android.saveCredentials(u, p, '', v2);
      }
      if ((u && p) || v2) setText('profile-creds', 'Salvo');
    } catch(e) {}
  }

  if (immediate) {
    if (_credsSaveTimer) { clearTimeout(_credsSaveTimer); _credsSaveTimer = null; }
    doSave();
  } else {
    if (_credsSaveTimer) clearTimeout(_credsSaveTimer);
    _credsSaveTimer = setTimeout(doSave, 250);
  }
}

/** Flush síncrono antes de conectar */
function flushCredentialsBeforeConnect() {
  detectEmbeddedCredentials();
  if (_hasEmbeddedCreds) return true; // Free/Config — nativo lê USER/PASS do JSON
  var u  = (($('ci-user') || {}).value || '').trim();
  var p  = (($('ci-pass') || {}).value || '').trim();
  var v2 = (($('ci-xray') || {}).value || '').trim();
  var needUser = isXrayMode ? !v2 : !(u && p);
  if (needUser) {
    // Mostra formulário e avisa
    var card = $('creds-card');
    if (card) card.style.display = 'block';
    toast(isXrayMode ? 'Informe o UUID XRay' : 'Informe usuário e senha', 'err');
    try { scrollToSection('creds-card'); } catch(e) {}
    return false;
  }
  autoSaveCredentials(true);
  return true;
}

/** Aplica modo SSH/XRay nos campos de login manual (só o necessário). */
function applyCredsModeUI() {
  var sshBox = $('creds-ssh-fields');
  var xrayBox = $('creds-xray-fields');
  var chipS = $('creds-chip-ssh');
  var chipX = $('creds-chip-xray');
  if (sshBox) sshBox.style.display = isXrayMode ? 'none' : 'block';
  if (xrayBox) xrayBox.style.display = isXrayMode ? 'block' : 'none';
  if (chipS) chipS.classList.toggle('on', !isXrayMode);
  if (chipX) chipX.classList.toggle('on', !!isXrayMode);
  var hint = $('creds-hint');
  if (hint) {
    hint.textContent = isXrayMode
      ? 'Modo XRay · informe só o UUID / vmess'
      : 'Modo SSH · informe usuário e senha';
  }
}

function setCredsMode(xray) {
  if (app.connected) { toast('Desconecte para alterar o modo.', 'err'); return; }
  autoSaveCredentials(true);
  isXrayMode = !!xray;
  applyCredsModeUI();
