}

function toggleCredsMode() {
  setCredsMode(!isXrayMode);
}
var _hasEmbeddedCreds = false;

/**
 * PRIVACIDADE: detecta se o servidor/Config já tem login embutido.
 * Nunca grava senha/UUID nos inputs — só checa se existem.
 */
function detectEmbeddedCredentials() {
  var user = '', pass = '', xray = '';
  try {
    var A_ = window.Android;
    if (A_ && typeof A_.getSavedCredentials === 'function') {
      var raw = A_.getSavedCredentials() || '{}';
      var creds = JSON.parse(raw);
      user = String(creds.sshUser || creds.user || '').trim();
      pass = String(creds.sshPass || creds.pass || creds.password || '').trim();
      xray = String(creds.xrayId || creds.uuid || '').trim();
    }
  } catch(e) {}
  _hasEmbeddedCreds = !!( (user && pass) || xray );
  return _hasEmbeddedCreds;
}

/** Meta dos servidores (hasAuth / isXray) sem expor senha na UI */
function getServersMeta(listKey) {
  var meta = [];
  try {
    var full = A.getFullConfig ? A.getFullConfig() : A.parse(A.call('getFullConfig'), {});
    var arr = listKey === 'multi' ? (full.MultiServs || []) : (full.Servers || []);
    if (!arr || !arr.length) return meta;
    for (var i = 0; i < arr.length; i++) {
      var s = arr[i] || {};
      var user = String(s.USER || s.Username || '').trim();
      var pass = String(s.PASS || s.Password || '').trim();
      var xray = String(s.xray_uuid || s.xray_id || '').trim();
      var xaddr = String(s.xray_address || '').trim();
      var mode = String(s.MODE || s.Mode || s.TYPE || s.Tunnel || '').toUpperCase();
      var isXray = !!(xray || xaddr || mode.indexOf('XRAY') >= 0 || mode.indexOf('V2RAY') >= 0);
      // FREE = tem USER+PASS ou UUID no Config (login automático)
      // PREMIUM tag = operadora SEM credenciais no Config (usuário digita)
      var hasAuth = !!(user && pass) || !!xray;
      meta.push({ position: i, hasAuth: hasAuth, isXray: isXray });
    }
  } catch(e) {}
  return meta;
}

