window.onCheckUserReceived = function(data) {
    var card = document.getElementById('checkuser-card');
    var emptyBtn = document.getElementById('btn-cu-check-empty');
    if (emptyBtn) emptyBtn.style.display = 'none';
    if (!card) return;
    card.classList.add('show');

    try {
        // Parse dos dados (suporta string ou objeto)
        var u = typeof data === 'string' ? JSON.parse(data) : data;
        if (!u) return;

        // --- NOME DO USUÁRIO ---
        var username = u.username || '—';
        document.getElementById('cu-username').textContent = username;

        // --- CONEXÕES (suporte a countConnection e count) ---
        var count = u.countConnection !== undefined ? u.countConnection : u.count;
        count = count !== undefined && count !== null ? count : '—';

        // --- LIMITE (suporte a limiterUser, limit e isUnlimited) ---
        var limit = '∞';
        var isUnlimited = u.isUnlimited || false;

        if (u.limiterUser !== undefined) {
            limit = u.limiterUser === '∞' || u.limiterUser === '0' ? '∞' : u.limiterUser;
            isUnlimited = u.limiterUser === '∞' || u.limiterUser === '0';
        } else if (u.limit !== undefined) {
            limit = u.limit === 0 ? '∞' : String(u.limit);
            isUnlimited = u.limit === 0;
        }

        document.getElementById('cu-connections').textContent = count + ' / ' + limit;

        // --- DATA DE EXPIRAÇÃO (suporte a expirationDate e expiry) ---
        var expiryDate = u.expirationDate || u.expiry || '—';
        document.getElementById('cu-expiration').textContent = expiryDate;

        // --- DIAS RESTANTES (suporte a expirationDays e expiryDays) ---
        var daysLeft = u.expirationDays !== undefined ? u.expirationDays : u.expiryDays;
        if (daysLeft === undefined || daysLeft === null) daysLeft = '—';

        var daysElement = document.getElementById('cu-days');

        // Limpa classes anteriores
        daysElement.className = 'cu-item-value';

        if (daysLeft !== '—') {
            var numDays = parseInt(daysLeft);
            if (!isNaN(numDays)) {
                if (numDays < 0) {
                    daysElement.textContent = '⚠️ Expirado há ' + Math.abs(numDays) + ' dias';
                    daysElement.classList.add('expiry-danger');
                } else if (numDays === 0) {
                    daysElement.textContent = '📅 Expira hoje!';
                    daysElement.classList.add('expiry-warning');
                } else if (numDays <= 3) {
                    daysElement.textContent = '⚡ ' + numDays + ' dias restantes';
                    daysElement.classList.add('expiry-warning');
                } else if (numDays <= 7) {
                    daysElement.textContent = '⏳ ' + numDays + ' dias restantes';
                    daysElement.style.color = '#fbbf24';
                } else {
                    daysElement.textContent = numDays + ' dias restantes';
                    daysElement.classList.add('expiry-safe');
                }
            } else {
                daysElement.textContent = daysLeft;
                daysElement.style.color = '#94a3b8';
            }
        } else {
            daysElement.textContent = '—';
            daysElement.style.color = '#94a3b8';
        }

        // --- STATUS (novo campo da API VPS) ---
        var status = u.status || 'unknown';

        // Remove status antigo se existir
        var oldStatusEl = document.getElementById('cu-status');
        if (oldStatusEl) {
            oldStatusEl.parentElement.remove();
        }

        // Cria novo elemento de status
        var parent = daysElement.parentElement;
        if (parent) {
            var statusDiv = document.createElement('div');
            statusDiv.className = 'cu-item';
            statusDiv.id = 'cu-status-container';

            var statusLabel = document.createElement('div');
            statusLabel.className = 'cu-item-label';
            statusLabel.textContent = 'Status';

            var statusValue = document.createElement('div');
            statusValue.className = 'cu-item-value';
            statusValue.id = 'cu-status';
            statusValue.style.fontWeight = '700';

            var statusMap = {
                'active': { text: '✅ Ativo', color: '#4CAF50' },
                'expired': { text: '⛔ Expirado', color: '#ef4444' },
                'locked': { text: '🔒 Bloqueado', color: '#f59e0b' },
                'not_found': { text: '❌ Não encontrado', color: '#6b7280' },
                'unknown': { text: '❓ Desconhecido', color: '#6b7280' }
            };
            var info = statusMap[status] || statusMap['unknown'];
            statusValue.textContent = info.text;
            statusValue.style.color = info.color;

            statusDiv.appendChild(statusLabel);
            statusDiv.appendChild(statusValue);

            // Insere após o item de dias
            parent.parentElement.insertBefore(statusDiv, parent.nextSibling);
        }

        // Salva dados para referência
        window._lastCheckUserData = u;

    } catch (e) {
        console.error('Erro ao processar CheckUser:', e);
    }
};

